var H = 6.62607015e-34; // Planck constant J·s
function wavelength(c, f){ if(f===0) return Infinity; return c/f; }
function frequency(c, lambda){ if(lambda===0) return Infinity; return c/lambda; }
function photonEnergyHz(f){ return H*f; }
function photonEnergyLambda(lambda){ if(lambda===0) return Infinity; return H*(299792458/lambda); }
var EXPORTS = { wavelength:wavelength, frequency:frequency, photonEnergyHz:photonEnergyHz, photonEnergyLambda:photonEnergyLambda, H:H };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WavelengthForgePure = EXPORTS; }
